import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Network","description":"","frontmatter":{},"headers":[],"relativePath":"manual/network.md","filePath":"manual/network.md"}'),i={name:"manual/network.md"};function o(l,e,r,p,d,h){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h1><p>The net surface lives behind <code>net-tool</code> (wizard) and the classic commands underneath it.</p><h2 id="address-setup" tabindex="-1">Address setup <a class="header-anchor" href="#address-setup" aria-label="Permalink to &quot;Address setup&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; &quot;obtain an address via DHCP&quot;</span></span>
<span class="line"><span>ush&gt; dhcp                   (the classic form - same call)</span></span>
<span class="line"><span>ush&gt; ip                     (show IP / mask / gateway)</span></span></code></pre></div><p>Static addressing through the wizard collects address, mask and gateway one field at a time, so the positional argument line can never be assembled in the wrong order. Classic form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; ip 10.0.2.15 255.255.255.0 10.0.2.2</span></span></code></pre></div><h2 id="name-resolution" tabindex="-1">Name resolution <a class="header-anchor" href="#name-resolution" aria-label="Permalink to &quot;Name resolution&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dns example.com              A record (+CNAME when present)</span></span>
<span class="line"><span>ush&gt; dns example.com aaaa         AAAA / cname / mx / txt / ns / srv</span></span>
<span class="line"><span>ush&gt; dnstest                      every record type against the resolver</span></span></code></pre></div><p>DNS goes through the configured resolver; under QEMU user-mode networking the slirp stack forwards to the real upstream.</p><h2 id="connectivity-tests" tabindex="-1">Connectivity tests <a class="header-anchor" href="#connectivity-tests" aria-label="Permalink to &quot;Connectivity tests&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; ping / wget / ssh / dnstest submenu</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /</span></span>
<span class="line"><span>ush&gt; wget https.example 443 /           (TLS is built in)</span></span></code></pre></div><p><code>ping</code> and <code>wget</code> ride the kernel NETCMD bridge - the exact syscall the historical apps used.</p><h2 id="wifi-and-bluetooth" tabindex="-1">WiFi and Bluetooth <a class="header-anchor" href="#wifi-and-bluetooth" aria-label="Permalink to &quot;WiFi and Bluetooth&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; net-tool               -&gt; WiFi manager: status / scan / test / sdio</span></span>
<span class="line"><span>ush&gt; wifi scan              (beacon-derived network list)</span></span>
<span class="line"><span>ush&gt; net-tool               -&gt; Bluetooth: status / usb / uart / test</span></span>
<span class="line"><span>ush&gt; bt                     (transport + controller status)</span></span></code></pre></div><p>The wireless layer reports honest states per family (ath, brcm, iwlwifi, rtlwifi): registered, scanning, connected - a machine without the hardware says so instead of pretending.</p><h2 id="firewall" tabindex="-1">Firewall <a class="header-anchor" href="#firewall" aria-label="Permalink to &quot;Firewall&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; firewall               (list rules + policies)</span></span>
<span class="line"><span>ush&gt; firewall add ...       (rule management - see the commands page)</span></span>
<span class="line"><span>ush&gt; firewall ct            (the connection-tracking table)</span></span></code></pre></div><h2 id="routing-and-arp" tabindex="-1">Routing and ARP <a class="header-anchor" href="#routing-and-arp" aria-label="Permalink to &quot;Routing and ARP&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; route                  (the full routing table)</span></span>
<span class="line"><span>ush&gt; route add 10.0.0.0 255.0.0.0 10.0.2.2</span></span>
<span class="line"><span>ush&gt; arp                    (the ARP cache)</span></span></code></pre></div><h2 id="ssh-in-and-out" tabindex="-1">SSH in and out <a class="header-anchor" href="#ssh-in-and-out" aria-label="Permalink to &quot;SSH in and out&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; sshd                   (serve the shell - port/user/pass optional)</span></span>
<span class="line"><span>ush&gt; ssh 10.0.2.2           (connect out; credentials as arguments)</span></span></code></pre></div><p>The SSH stack runs the real KEX/cipher flow; host keys can be pre-seeded on the /etc volume for unattended boots. Under QEMU, forward a port with <code>-netdev user,hostfwd=tcp::2223-:22</code> and connect from the host.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No IP after DHCP</strong> - check the NIC model (<code>hwinfo</code> -&gt; PCI) and that the <code>-netdev user</code> exists; the e1000 family is the best-tested.</li><li><strong>DNS times out</strong> - the slirp DNS forward only works with user-mode networking; on a bridged tap you need a real resolver.</li><li><strong>First SSH connect stalls</strong> - the ARP cache is cold after DHCP; run one client-direction command first (<code>ping</code> the peer) to warm it, then connect.</li></ul><p>More: <a href="./../troubleshooting/network-issues.html">../troubleshooting/network-issues.md</a>.</p>`,25)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
